{
  "name": "instacart",
  "/store/account/orders": {
    "pageSubType": 1,
    "deepScrape": {
      "enabled": true,
      "returnType": "json",
      "maxPageNumbers": 3,
      "httpConfig": [
        {
          "url": "https://www.instacart.com/v3/orders?page={pageNumber}",
          "method": "GET"        
        }
      ]
    },
    "orders": [
      {
          "scriptJson": {},
          "row": {
              "selector": "orders"
          },
          "orderID": {
              "selector": "id"
          },
          "cartTotal": {
              "selector": "total"
          },
          "orderDate": {
              "selector": "created_at",
              "manipulator":"formatDate:MMM DD, YYYY"
          },
          "subMerchant": {
              "selector": "order_deliveries[0].retailer.name",
              "useDefault": null
          }
      }
  ],
  "products": [
      {
          "scriptJson": {},
          "row": {
              "selector": "order_deliveries[ALL].order_items"
          },
          "name": {
              "selector": "item.name"
          },
          "productID": {
              "selector": "item.product_id"
          }
      }
  ]
  },
  "/store/orders/*": {
    "pageSubType": 2,
    "orders": [
      {
        "cartTotal": {
          "selector": "#react-views-container div.css-1ohljjf > p:nth-child(2)"
        },
        "orderDate": {
          "selector": ".order-status-order-info div p",
          "manipulator": "splitGetByIndexLast:on ::splitGetByIndex:at: 0::formatDate:MMMM DD, YYYY"
        },
        "subMerchant": {
          "selector": ".order-summary-header h3",
          "manipulator": "splitGetByIndex:Summary:0"
        },
        "orderID": {
          "selector": "",
          "useUrl": true,
          "manipulator": "splitGetByIndexLast:/"
        }
      }
    ],
    "products": [
      {
        "row": {
          "selector": ".order-summary-items ul.order-item-list li"
        },
        "name": {
          "selector": ".order-status-item-details h5"
        },
        "qty": {
          "selector": ".order-status-item-qty",
          "manipulator": "splitGetByIndex:x:0::splitGetByIndex: :0"
        },
        "price": {
          "selector": ".order-status-item-price p, .order-status-item-price strong"
        }
      }
    ]
  }
}

